  "ÉQUIPIER BANQUET": {"secteur": "Restauration", "alias": ["Équipier de banquet"], "postes": ["Équipier banquet"], "zones": null, "effectifLabel": null, "groupes": [{"label": "Profil / compétences / qualifications", "options": [["Expérience en restauration", true], ["Montage et démontage de salles", true], ["Service et manutention", true], ["Travail en équipe", true]], "autre": true}, {"label": "Tâches à réaliser", "options": [["Installation des tables et chaises", true], ["Mise en place des salles", true], ["Dressage des tables", true], ["Transport de matériel et de vaisselle", true], ["Service des boissons et plats", true], ["Débarrassage", true], ["Rangement et nettoyage", true], ["Manutention des équipements", true]], "autre": true}, {"label": "Machines, produits et matériels utilisés", "options": [["Tables et chaises", true], ["Plateaux", true], ["Chariots / dessertes", true], ["Vaisselle et verrerie", true], ["Matériel de service", true], ["Équipements de montage", true], ["Produits d'entretien", true]], "autre": true}], "questions": [{"label": "Formation générale à la sécurité et formation au poste prévues", "options": ["Oui", "Non", "À confirmer"]}, {"label": "Formation au poste réalisée", "options": ["Oui", "Non", "À prévoir"]}], "risques": [["Manutention : lombalgies, TMS", "Limiter les charges, utiliser des chariots et diables, stocker le matériel de façon stable et accessible. Porter les charges à plusieurs si nécessaire et former aux gestes et postures adaptés.", true], ["Chutes de plain-pied", "Nettoyer immédiatement les sols humides ou souillés, dégager les circulations, signaler les obstacles et assurer un éclairage suffisant. Porter des chaussures antidérapantes.", true], ["Postures contraignantes / gestes répétitifs", "Limiter le poids des plateaux, adapter les rangements, alterner les tâches et prévoir des pauses. Garder les charges près du corps et éviter les torsions du dos.", true], ["Chutes dans les escaliers", "Maintenir les escaliers dégagés, propres et éclairés ; utiliser les mains courantes et respecter les consignes de circulation. Porter des chaussures antidérapantes.", true], ["Pratiques addictives / fatigue", "Organiser les horaires et les pauses, prévenir les amplitudes excessives et sensibiliser le personnel aux risques liés aux consommations de substances psychoactives.", true], ["Collisions entre personnels", "Organiser les flux de circulation, signaler les déplacements, notamment avec des plateaux ou du matériel encombrant, et maintenir les passages dégagés.", true], ["Risques psychosociaux / violences externes", "Favoriser la communication, répartir la charge de travail, anticiper les périodes d'affluence et définir les consignes à suivre en cas de conflit avec un client.", true], ["Brûlures", "Prévenir les collègues lors du transport de plats chauds, ne pas surcharger les plateaux et utiliser des dessertes ainsi que des protections thermiques adaptées.", true], ["Coupures", "Manipuler la vaisselle avec précaution, ne jamais ramasser les débris à mains nues et utiliser des conteneurs adaptés. Mettre à disposition des gants anticoupures pour le ramassage sécurisé des débris.", true], ["Risques liés au trajet", "Préparer son itinéraire, respecter le Code de la route, ne pas utiliser son téléphone au volant et éviter de conduire en cas de fatigue. Sécuriser les accès et parkings.", true], ["Risques thermiques", "Limiter les expositions au froid ou à la chaleur, prévoir des vêtements adaptés et des pauses dans une zone tempérée. Si l'accès à une chambre froide est prévu, vérifier l'ouverture intérieure et le dispositif d'alarme.", true], ["Risques chimiques", "Respecter les étiquettes, dosages et fiches de données de sécurité (FDS). Ne jamais mélanger les produits. Assurer une ventilation adaptée et porter les gants, lunettes ou vêtements de protection nécessaires.", true]], "epi": [["Chaussures antidérapantes", true], ["Chaussures de sécurité", true], ["Gants de manutention", true], ["Gants anticoupures adaptés", true], ["Gants thermiques si nécessaire", false], ["Vêtements de travail adaptés", true], ["Lunettes de protection si nécessaire", false]], "epiAutre": true, "complements": [], "sir": "Non", "descriptif": "L'équipier banquet installe et démonte les salles de réception : tables, chaises, nappage et dressage selon le plan de l'événement.\nIl transporte le matériel et la vaisselle, participe au service des boissons et des plats pendant l'événement puis au débarrassage et au rangement.\nPoste physique, avec manutention de mobilier, horaires décalés et pics d'activité liés aux événements."}
