// Modèle de fiche d'une qualification de l'onglet Qualifications : par intitulé (casse et accents ignorés)
// ou par alias (ex. « Réceptionniste » → RÉCEPTIONNISTE DE JOUR). null si Adaptel n'a pas encore de modèle.
function modeleFiche(nomQualif) {
  const norm = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
  const n = norm(nomQualif);
  const titre = Object.keys(FICHES_MODELES).find(t => norm(t) === n || FICHES_MODELES[t].alias.some(a => norm(a) === n));
  return titre ? FICHES_MODELES[titre] : null;
}
